Inductive Nat : Type :=
  | Z : Nat
  | S : Nat -> Nat.

Fixpoint add (a b : Nat) : Nat :=
  match a with
  | Z => b
  | S a => S (add a b)
  end.

Inductive Bx (A : Type) : Type :=
  | MkBx : A -> Bx A.
Arguments MkBx {A}.

Inductive Pr (A B : Type) : Type :=
  | MkP : A -> B -> Pr A B.
Arguments MkP {A B}.

Inductive Opt (A : Type) : Type :=
  | No : Opt A
  | Yes : A -> Opt A.
Arguments No {A}.
Arguments Yes {A}.

Inductive Lst (A : Type) : Type :=
  | Nl : Lst A
  | Cs : A -> Lst A -> Lst A.
Arguments Nl {A}.
Arguments Cs {A}.

Definition ubx {A : Type} (b : Bx A) : A :=
  match b with
  | MkBx x => x
  end.

Definition swp {A B : Type} (p : Pr A B) : Pr B A :=
  match p with
  | MkP a b => MkP b a
  end.

Definition pmap {A B C : Type} (f : A -> B) (p : Pr A C) : Pr B C :=
  match p with
  | MkP a c => MkP (f a) c
  end.

Definition getor {A : Type} (d : A) (v : Opt A) : A :=
  match v with
  | No => d
  | Yes x => x
  end.

Definition omap {A B : Type} (f : A -> B) (v : Opt A) : Opt B :=
  match v with
  | No => No
  | Yes x => Yes (f x)
  end.

Fixpoint llen {A : Type} (xs : Lst A) : Nat :=
  match xs with
  | Nl => Z
  | Cs h t => S (llen t)
  end.

Inductive K0 : Type :=
  | Ka0 : Nat -> K0
  | Kb0 : K0.

Definition bx0 (x : K0) : Bx (Bx (K0)) := MkBx (MkBx (x)).

Definition ub0 (b : Bx (Bx (K0))) : K0 := ubx (ubx (b)).

Definition sw0 (p : Pr K0 Nat) : Pr Nat K0 := swp p.

Definition pm0 (p : Pr Nat K0) : Pr K0 K0 := pmap (fun x => Ka0 x) p.

Definition go0 (v : Opt K0) : K0 := getor Kb0 v.

Definition om0 (v : Opt Nat) : Opt K0 := omap (fun x => Ka0 x) v.

Definition ln0 (xs : Lst (Pr K0 Nat)) : Nat := llen xs.

Definition cs0 (x y : K0) : Lst K0 := Cs x (Cs y Nl).

